const d = $input.first().json;
const hoy = new Date().toISOString().slice(0, 10);
const tieneSitio = !!d.sitio_web;
const hallazgos = [
  {
    fuente: 'SIMULADO - Firecrawl scrape (pagina web)',
    resultado: tieneSitio ? 'giro_coincide' : 'sin_sitio',
    detalle: tieneSitio
      ? '[DATO SIMULADO] La pagina ' + d.sitio_web + ' describe actividades compatibles con el giro declarado "' + d.giro_declarado + '". No se consulto el sitio real.'
      : '[DATO SIMULADO] El proveedor no declaro sitio web.',
    fecha_fuente: hoy,
  },
  {
    fuente: 'SIMULADO - Firecrawl search (noticias)',
    resultado: 'sin_noticias',
    detalle: '[DATO SIMULADO] Busqueda ficticia "' + d.razon_social + ' fraude / demanda / SAT / EFOS" sin resultados negativos. Enlaces de ejemplo: https://ejemplo.invalid/noticia-simulada-1. No es una consulta oficial al SAT ni a listas EFOS.',
    fecha_fuente: hoy,
  },
  {
    fuente: 'SIMULADO - WHOIS/RDAP (antiguedad del dominio)',
    resultado: tieneSitio ? 'dominio_establecido' : 'sin_dato',
    detalle: tieneSitio
      ? '[DATO SIMULADO] Dominio ' + d.dominio + ' con fecha de registro ficticia 2015-03-10 (aprox. 11 anios).'
      : '[DATO SIMULADO] Sin dominio para consultar.',
    fecha_fuente: hoy,
  },
];
const resumen_ia = '[RESUMEN SIMULADO - NO GENERADO POR IA] Proveedor ' + d.razon_social + ' (RFC ' + d.rfc + '). ' +
  (tieneSitio ? 'El sitio web parece coincidir con el giro declarado. ' : 'No declaro sitio web. ') +
  'No se encontraron noticias negativas en la busqueda simulada. ' +
  'Estos hallazgos son de ejemplo y no sustituyen consultas oficiales (SAT, OFAC). Sin puntaje ni decision.';
return [{ json: { proveedor_id: d.proveedor_id, hallazgos, resumen_ia } }];

const d = $('Preparar datos del proveedor').first().json;
const hoy = new Date().toISOString().slice(0, 10);
function leer(nombre) { try { return $(nombre).all().map(i => i.json); } catch (e) { return []; } }

function errorDe(x) { if (!x || !x.error) return ''; const e = x.error; return typeof e === 'string' ? e : (e.message || JSON.stringify(e)); }

// Pagina web
const scrape = leer('Firecrawl: leer sitio web')[0] || {};
const errWeb = errorDe(scrape);
const contenido = errWeb ? '' : ((scrape.data && scrape.data.markdown) || scrape.markdown || '');
const webOk = !!d.sitio_web && !!contenido;
let hWeb;
if (!d.sitio_web) {
  hWeb = { fuente: 'web', resultado: 'sin_sitio', detalle: 'El proveedor no declaro sitio web.', fecha_fuente: hoy };
} else if (webOk) {
  hWeb = { fuente: 'web', resultado: 'pendiente_ia', detalle: 'Contenido leido de ' + d.sitio_web, fecha_fuente: hoy };
} else {
  hWeb = { fuente: 'web', resultado: 'sin_dato', detalle: 'FALLO de la fuente al leer ' + d.sitio_web + ': ' + (errWeb || 'la respuesta no trajo contenido') + '.', fecha_fuente: hoy };
}

// Noticias
const busq = leer('Firecrawl: buscar noticias negativas');
const errBusq = busq.map(errorDe).filter(Boolean).join(' | ') || (busq.length ? '' : 'sin respuesta de la fuente');
let resultados = [];
for (const r of busq) {
  const data = r.data !== undefined ? r.data : r;
  if (Array.isArray(data)) resultados.push(...data);
  else if (data && typeof data === 'object') {
    for (const k of ['web', 'news']) if (Array.isArray(data[k])) resultados.push(...data[k].map(x => ({ ...x, _origen: k })));
    if (data.url) resultados.push(data);
  }
}
const negativas = /fraude|defraud|demandad[oa]s?\b|demanda (judicial|penal|mercantil|laboral|contra|por)|denuncia|efos|69-?b|operaciones simuladas|factureras?|empresas? fantasma|lista negra|embargo|evasi[oó]n fiscal|lavado de dinero/i;
const enlaces = resultados.filter(x => x && x.url).map(x => ({ titulo: x.title || '', url: x.url, texto: (x.description || x.snippet || x.markdown || '').slice(0, 1500), origen: x._origen || 'web', fecha: x.date || '' }));

// FILTRO ESTRICTO DE RELEVANCIA. Que aparezca el nombre, el RFC o el dominio NO basta.
// Un enlace se acepta solo si: (1) no es documentacion tecnica, repositorio, foro tecnico ni articulo academico,
// (2) identifica a la ENTIDAD (RFC, o nombre junto a figura juridica o palabra de empresa) y
// (3) la nota trata sobre ella (nombre/RFC en el titulo o junto a un verbo de hecho noticioso).
function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9& ]+/g, ' ').replace(/ +/g, ' ').trim(); }
const sufijos = / (s a p i|sapi|s a b|sab|s a|sa|s de r l|s de rl|srl|s c|sc|a c|ac|de c v|de cv|de r l|de rl|cv|sas)$/;
let nucleo = norm(d.razon_social);
for (let i = 0; i < 4; i++) nucleo = nucleo.replace(sufijos, '').trim();
const rfcN = norm(d.rfc).replace(/ /g, '');
const dom = (d.dominio || '').toLowerCase();
const genericas = ['example','ejemplo','domain','dominio','test','prueba','demo','sample','web','site','sitio','online','global','group','grupo','services','servicios','solutions','soluciones','company','compania','empresa','mexico','international','internacional','digital','tech','data','systems','sistemas','consulting','comercial','comercializadora','corporativo','industrial','de','del','la','el','los','las','y','the','of','and'];
const nombreGenerico = nucleo.length < 4 || nucleo.split(' ').every(w => genericas.includes(w));
const hostsTecnicos = ['github.com','gitlab.com','bitbucket.org','sourceforge.net','stackoverflow.com','stackexchange.com','npmjs.com','pypi.org','readthedocs.io','sourceware.org','apache.org','w3.org','ietf.org','rfc-editor.org','iana.org','oracle.com','microsoft.com','developer.apple.com'];
const hostsAcademicos = ['arxiv.org','acm.org','ieee.org','springer.com','sciencedirect.com','researchgate.net','semanticscholar.org','scholar.google.com','jstor.org','nature.com','wiley.com','vldb.org','ijcai.org','aaai.org','ssrn.com','mdpi.com','plos.org','nih.gov','scielo.org','redalyc.org','academia.edu'];
const prefijosTecnicos = ['docs.','doc.','developer.','developers.','api.','repository.','repo.','forum.','forums.','community.','support.','help.','learn.','wiki.'];
const rutasTecnicas = ['/docs/','/doc/','/documentation/','/api/','/sdk','/pipermail/','/forums/','/forum/','/proceedings/','/doi/','/javadoc','/reference/','/thread/'];
// Los PDF NO se descartan por su formato: pasan por las mismas reglas de fuente y contenido que cualquier enlace.
function esPdf(u) { return /[.]pdf([?#]|$)/i.test(String(u || '')); }
const textoTecnico = ['cited by','citado por','proceedings','index of','et al','doi','javadoc','sdk','pull request','repository','repositorio','arxiv'];
const palabrasEntidad = ['empresa','compania','proveedor','proveedora','firma','sociedad','corporativo','contribuyente','razon social','company','firm','corporation','s a de c v','sa de cv','s de r l','sapi'];
const verbosNoticia = ['acus','demand','sancion','multa','investig','denunci','fraud','embarg','clausur','anunci','inaugur','firm','contrat','adquir','report','inform','detuv','vincul','senal','public','incluy','list','opera','invier','abre','cierra','expand','gan','perd','quiebr','concurso','licit'];
function host(u) { const m = String(u || '').toLowerCase().match(/^[a-z][a-z0-9+.-]*:[/][/]([^/?#:]+)/); return m ? m[1].replace(/^www[0-9]*[.]/, '') : ''; }
function contiene(t, frase) { return (' ' + t + ' ').includes(' ' + frase + ' '); }
function evaluar(e) {
  const h = host(e.url);
  const ruta = String(e.url || '').toLowerCase();
  const tit = norm(e.titulo);
  const t = norm(e.titulo + ' ' + e.texto);
  if (dom && (h === dom || h.endsWith('.' + dom))) return 'sitio propio del proveedor, no es noticia de terceros';
  if (hostsAcademicos.some(x => h === x || h.endsWith('.' + x)) || h.endsWith('.edu') || h.includes('.edu.') || h.includes('.ac.')) return 'articulo o fuente academica';
  if (hostsTecnicos.some(x => h === x || h.endsWith('.' + x)) || prefijosTecnicos.some(p => h.startsWith(p))) return 'documentacion tecnica, repositorio o foro tecnico';
  if (rutasTecnicas.some(p => ruta.includes(p))) return 'documento tecnico o foro tecnico';
  const senalesTec = textoTecnico.filter(w => contiene(t, w));
  if (senalesTec.length) return 'contenido tecnico o academico (' + senalesTec.join(', ') + ')';
  const rfcEn = rfcN.length >= 12 && t.replace(/ /g, '').includes(rfcN);
  const iNom = nucleo.length >= 4 ? (' ' + t + ' ').indexOf(' ' + nucleo + ' ') : -1;
  if (!rfcEn && iNom < 0) return 'no menciona la razon social ni el RFC (el dominio solo no identifica a la entidad)';
  const ventana = iNom >= 0 ? t.slice(Math.max(0, iNom - 80), iNom + nucleo.length + 80) : '';
  const despues = iNom >= 0 ? t.slice(iNom + nucleo.length, iNom + nucleo.length + 25) : '';
  const conFigura = / (s a|sa|s de r l|sapi|sab|sc|ac|sas|inc|llc|ltd|corp)( |$)/.test(despues);
  const conPalabra = palabrasEntidad.some(w => contiene(ventana, w));
  if (!rfcEn && !conFigura && !conPalabra) return 'coincidencia generica: el nombre aparece sin contexto que identifique a una empresa';
  if (nombreGenerico && !rfcEn && !conFigura) return 'nombre generico: se exige RFC o razon social con figura juridica';
  const enTitulo = rfcEn ? tit.replace(/ /g, '').includes(rfcN) || (iNom >= 0 && contiene(tit, nucleo)) : contiene(tit, nucleo);
  const conHecho = verbosNoticia.some(v => (' ' + ventana).includes(' ' + v));
  if (!enTitulo && !conHecho) return 'sin relacion clara: la nota no trata sobre la empresa';
  return '';
}
const aceptados = [];
const rechazados = [];
for (const e of enlaces) { const motivo = evaluar(e); if (motivo) rechazados.push({ ...e, motivo }); else aceptados.push(e); }
const negativos = aceptados.filter(e => negativas.test(e.titulo + ' ' + e.texto));
const q = '"' + d.razon_social + '" fraude OR demanda OR SAT OR EFOS';
const txtAcept = aceptados.map(e => (esPdf(e.url) ? '[PDF] ' : '') + e.titulo + ' - ' + e.url + (e.fecha ? ' (' + e.fecha + ')' : '')).join(' | ');
const revisados = enlaces.length;
const base = revisados + ' enlace(s) revisado(s), ' + aceptados.length + ' fuente(s) relevante(s)';
let hNoticias;
if (errBusq) {
  hNoticias = { fuente: 'noticias', resultado: 'sin_dato', detalle: 'FALLO de la fuente en la busqueda de noticias: ' + errBusq + '. 0 enlace(s) revisado(s), 0 fuente(s) relevante(s). Motivo de sin_dato: la busqueda fallo y no fue posible evaluar noticias.', fecha_fuente: hoy };
} else if (negativos.length) {
  hNoticias = { fuente: 'noticias', resultado: 'noticias_negativas', detalle: base + ', ' + negativos.length + ' con terminos negativos (revisar manualmente): ' + txtAcept + '.', fecha_fuente: hoy };
} else if (aceptados.length) {
  hNoticias = { fuente: 'noticias', resultado: 'sin_noticias', detalle: base + ', sin terminos negativos: ' + txtAcept + '.', fecha_fuente: hoy };
} else {
  hNoticias = { fuente: 'noticias', resultado: 'sin_dato', detalle: base + '. Motivo de sin_dato: ' + (revisados ? 'ningun enlace es una fuente verificable que identifique al proveedor' : 'la busqueda no devolvio enlaces') + '; no fue posible evaluar noticias.', fecha_fuente: hoy };
}
const filtro_noticias = { busqueda: q, revisados, aceptados: aceptados.map(e => ({ titulo: e.titulo, url: e.url, pdf: esPdf(e.url) })), descartados: rechazados.map(e => ({ titulo: e.titulo, url: e.url, pdf: esPdf(e.url), motivo: e.motivo })) };

// Dominio
let rdap = leer('RDAP: consultar antigüedad del dominio')[0] || {};
const errRdap = errorDe(rdap);
if (typeof rdap.data === 'string') { try { rdap = JSON.parse(rdap.data); } catch (e) { rdap = {}; } }
const ev = Array.isArray(rdap.events) ? rdap.events.find(e => e.eventAction === 'registration') : null;
let hDom;
if (ev && ev.eventDate && Number.isFinite(Date.parse(ev.eventDate)) && Date.parse(ev.eventDate) <= Date.now()) {
  const edadMs = Date.now() - Date.parse(ev.eventDate);
  const anios = edadMs / (365.25 * 24 * 3600 * 1000);
  hDom = {
    fuente: 'dominio',
    resultado: edadMs < 182 * 24 * 3600 * 1000 ? 'dominio_reciente' : 'dominio_antiguo',
    detalle: 'Dominio ' + d.dominio + ' registrado el ' + ev.eventDate.slice(0, 10) + ' (' + anios.toFixed(1) + ' anios).',
    fecha_fuente: ev.eventDate.slice(0, 10),
  };
} else {
  hDom = { fuente: 'dominio', resultado: 'sin_dato', detalle: !d.dominio ? 'Sin dominio para consultar.' : (errRdap ? 'FALLO de la fuente RDAP para ' + d.dominio + ': ' + errRdap + '.' : 'RDAP no devolvio fecha de registro para ' + d.dominio + '.'), fecha_fuente: hoy };
}

return [{ json: {
  proveedor_id: d.proveedor_id,
  razon_social: d.razon_social,
  rfc: d.rfc,
  giro_declarado: d.giro_declarado,
  sitio_web: d.sitio_web,
  contenido_web: contenido.slice(0, 6000),
  filtro_noticias,
  hallazgos: [hWeb, hNoticias, hDom],
} }];

