={{ JSON.stringify({
  model: "qwen/qwen3.8-27b",
  messages: [
    { role: "system", content: "Eres un analista de cumplimiento. Solo describes hallazgos. Nunca asignes puntajes, niveles o calificaciones de riesgo, ni recomiendes aprobar, continuar, rechazar o bloquear al proveedor. Responde únicamente con un objeto JSON válido con giro_resultado, giro_detalle y resumen. Si no hay contenido del sitio, usa giro_resultado sin_sitio. No inventes datos del SAT, OFAC ni de ninguna fuente oficial. SAT 69, SAT 69-B y OFAC no se consultan en este flujo: escribe siempre 'SAT 69/69-B y OFAC no fueron consultados por este flujo.'" },
    { role: "user", content: `Proveedor: ${$json.razon_social} (RFC ${$json.rfc})\nGiro declarado: ${$json.giro_declarado}\nSitio web: ${$json.sitio_web || 'no declarado'}\nContenido del sitio: ${String($json.contenido_web || '').slice(0, 12000)}\nHallazgos ya normalizados: ${JSON.stringify($json.hallazgos)}\nFuentes NO consultadas por este flujo: SAT 69, SAT 69-B (EFOS) y OFAC.\nSi noticias es sin_dato, di que no se pudo determinar; no digas que no hay noticias.\nDevuelve SOLO JSON con este formato: {\"giro_resultado\":\"giro_coincide|giro_no_coincide|sin_sitio\",\"giro_detalle\":\"explicacion breve\",\"resumen\":\"resumen en espanol de 3 a 5 frases\"}` }
  ],
  response_format: { type: "json_object" },
  max_completion_tokens: 1024
}) }}

parameters.jsCode:
const base = $('Normalizar hallazgos reales').first().json;
const r = $input.first().json;
const fallo = (msg) => {
  const hallazgos = base.hallazgos.map(h => h.resultado === 'pendiente_ia'
    ? { ...h, resultado: 'sin_dato', detalle: h.detalle + '. FALLO de Qwen al comparar el giro: ' + msg }
    : h);
  return [{ json: {
    proveedor_id: base.proveedor_id,
    hallazgos,
    resumen_ia: 'NO GENERADO: la llamada a Qwen fallo (' + msg + '). Revisar los hallazgos manualmente. SAT 69/69-B y OFAC no fueron consultados por este flujo.'
  } }];
};
if (r.error) {
  const msg = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return fallo(msg);
}
const texto = r.choices?.[0]?.message?.content;
if (typeof texto !== 'string' || !texto.trim()) return fallo('respuesta vacia de Groq');
let ia;
try { ia = JSON.parse(texto); } catch (e) { return fallo('JSON invalido de Groq'); }
if (!ia || typeof ia !== 'object') return fallo('respuesta inesperada de Groq');
const validos = ['giro_coincide', 'giro_no_coincide', 'sin_sitio'];
const hallazgos = base.hallazgos.map(h => {
  if (h.resultado !== 'pendiente_ia') return h;
  if (validos.includes(ia.giro_resultado)) return { ...h, resultado: ia.giro_resultado, detalle: h.detalle + '. ' + (ia.giro_detalle || '') };
  return { ...h, resultado: 'sin_dato', detalle: h.detalle + '. La IA no devolvio una comparacion valida; revisar manualmente.' };
});
const LEYENDA = 'SAT 69/69-B y OFAC no fueron consultados por este flujo.';
const listas = /(sat|69-?b|efos|ofac|lista negra)/i;
const afirmaLimpio = /(limpi|sin hallazgos|sin registros|sin coincidencias|no aparece|no figura|no esta listad|no está listad|no se encontr|no se identific|no registra|no tiene antecedentes|libre de)/i;
let resumen = String(ia.resumen || 'Sin resumen generado por la IA.');
const frases = resumen.split(/(?<=[.!?])\s+/);
resumen = frases.filter(f => f.includes('no fueron consultados') || !(listas.test(f) && afirmaLimpio.test(f))).join(' ').trim();
if (!resumen.includes(LEYENDA)) resumen = (resumen ? resumen + ' ' : '') + LEYENDA;
return [{ json: { proveedor_id: base.proveedor_id, hallazgos, resumen_ia: resumen } }];
